/* =====================================================================
   sprites.js — SIGAMOS visual sprites (cards, title, mascots)
   ---------------------------------------------------------------------
   - .card-fan     → the 3 overlapping cards: solid colored border,
                      50%-transparent colored fill, with the title
                      ("Sigamos" / "You Got This!") centered on top of
                      the middle of the stack.
   - CAR_GIF        → your uploaded bubu-car-bubu-running.gif, with the
                      bottom "running legs" speed-lines cropped off, used
                      peeking above the study-deck cards.
   - DUDU_GIF       → your uploaded dudu-dudu-bubu.gif, used on the
                      "Mensajitos" note screen.

   Include this BEFORE the main app script (and before sounds.js is
   fine either order, they don't depend on each other):
     <script src="sprites.js"></script>
     <script src="sounds.js"></script>
     <script> ... app code ... </script>
   ===================================================================== */
(function () {
  const CAR_GIF  = "data:image/gif;base64,";
  const DUDU_GIF = "data:image/gif;base64,";
  const CRY_GIF   = "data:image/gif;base64,";
  const FIGHT_GIF = "data:image/gif;base64,";

  const css = `
  /* --- 3-card fan: solid border, 50%-transparent fill, title centered on top --- */
  .card-fan{
    position:relative; width:min(260px,62vw); height:190px;
    margin:0 auto 6px;
  }
  .card-fan .fan-card{
    position:absolute; left:50%; top:6px; width:120px; height:168px;
    border-radius:18px; border:6px solid; box-shadow:0 10px 22px rgba(130,55,85,.18);
  }
  .card-fan .c-blue  {background:rgba(66,182,255,.5);  border-color:#36aff2; transform:translateX(-96px) rotate(-14deg)}
  .card-fan .c-yellow{background:rgba(255,217,79,.5);  border-color:#ffd743; transform:translateX(-60px) rotate(-3deg)}
  .card-fan .c-red   {background:rgba(255,62,72,.5);   border-color:#ff3d49; transform:translateX(-24px) rotate(13deg)}

  /* big variant (home screen "Sigamos") */
  .card-fan.big{ width:min(360px,90vw); height:262px; margin:0 auto 12px; }
  .card-fan.big .fan-card{ top:8px; width:160px; height:224px; border-radius:24px; border-width:8px; }
  .card-fan.big .c-blue  {transform:translateX(-128px) rotate(-14deg)}
  .card-fan.big .c-yellow{transform:translateX(-80px) rotate(-3deg)}
  .card-fan.big .c-red   {transform:translateX(-32px) rotate(13deg)}
  .card-fan.big .fan-title{ font-size:clamp(3rem,15vw,5.4rem); -webkit-text-stroke:3px #ff5f5f; text-shadow:3px 4px 0 #ff8a6b,6px 7px 0 #ff5f5f; }

  /* title sits centered ON TOP of the fan, not below it */
  .card-fan .fan-title{
    position:absolute; inset:0; display:flex; align-items:center; justify-content:center;
    text-align:center; padding:0 8px; z-index:3;
    font-family:"Luckiest Guy",cursive;
    font-size:clamp(1.7rem,7vw,3rem);
    color:#fff8ec;
    -webkit-text-stroke:2px #ff5f5f;
    paint-order:stroke fill;
    text-shadow:2px 3px 0 #ff8a6b,4px 5px 0 #ff5f5f;
    pointer-events:none;
  }

  /* --- mascots: real gifs instead of a drawn SVG --- */
  .mascot-gif{ display:block; object-fit:contain; }
  .mascot-gif.deck-car{
    position:absolute; z-index:12; left:50%; top:-30px; width:118px; height:auto;
    transform:translateX(-50%); pointer-events:none;
    filter:drop-shadow(0 5px 4px rgba(75,40,50,.16));
  }
  .mascot-gif.note-dudu{ width:130px; height:auto; margin:6px auto; }
  .mascot-gif.result-gif{ width:150px; height:auto; margin:6px auto; }
  .fan-title.long{ font-size:clamp(1.25rem,6.4vw,1.75rem); line-height:1.08; width:78%; text-align:center; }
  `;
  const style = document.createElement("style");
  style.textContent = css;
  document.head.appendChild(style);

  // Returns markup for the 3-card fan with `title` centered on top of it.
  // Only pass trusted, static strings (no user-entered text).
  window.renderCardFan = function (title, size) {
    return `
    <div class="card-fan${size === "big" ? " big" : ""}">
      <div class="fan-card c-blue"></div>
      <div class="fan-card c-yellow"></div>
      <div class="fan-card c-red"></div>
      <div class="fan-title${size === "long" ? " long" : ""}">${title}</div>
    </div>`;
  };

  // Returns the bubu-car gif, positioned to peek above the study deck.
  window.renderDeckMascot = function () {
    return `<img class="mascot-gif deck-car" src="${CAR_GIF}" alt="Bubu en su carrito">`;
  };

  // Same driving-Dudu gif, used large for the Examen intro (drives right → left).
  window.renderBigCar = function () {
    return `<img class="big-car" src="${CAR_GIF}" alt="">`;
  };

  // Mascot for the result pages: "cry" (try again), "close" (fighting) or the default dudu-bubu.
  window.renderResultMascot = function (kind) {
    if (kind === "cry") return `<img class="mascot-gif result-gif" src="${CRY_GIF}" alt="Llorando">`;
    if (kind === "close") return `<img class="mascot-gif result-gif" src="${FIGHT_GIF}" alt="Peleando">`;
    return window.renderNoteMascot();
  };

  // Returns the dudu-bubu gif for the note ("Mensajitos") screen.
  window.renderNoteMascot = function () {
    return `<img class="mascot-gif note-dudu" src="${DUDU_GIF}" alt="Dudu y Bubu">`;
  };
})();
